<?php
declare(strict_types=1); require_once __DIR__ . '/../config/db.php'; require_once __DIR__ . '/../includes/layout.php'; requireAdmin();
if ($_SERVER['REQUEST_METHOD']==='POST') { verifyCsrf($_POST['csrf_token'] ?? null); $id=filter_input(INPUT_POST,'payment_id',FILTER_VALIDATE_INT); $action=$_POST['action']??''; if(!$id || !in_array($action,['approved','rejected'],true)) redirectWith('payments.php','error','Invalid payment action.'); $stmt=$pdo->prepare("UPDATE payments p JOIN invoices i ON i.id=p.invoice_id SET p.status=:status, p.paid_at=CASE WHEN :status='approved' THEN NOW() ELSE NULL END, i.status=CASE WHEN :status='approved' THEN 'paid' ELSE 'unpaid' END WHERE p.id=:id AND p.status='pending'"); $stmt->execute([':status'=>$action,':id'=>$id]); redirectWith('payments.php','success','Payment review saved.'); }
$payments=$pdo->query('SELECT p.*, u.full_name, i.month_year FROM payments p JOIN users u ON u.id=p.tenant_id JOIN invoices i ON i.id=p.invoice_id ORDER BY p.created_at DESC')->fetchAll(); pageHeader('Payments'); ?><div class="rounded-lg border border-slate-200 bg-white p-6 shadow-sm"><h1 class="text-2xl font-bold">Payment review</h1><div class="mt-5 overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr class="border-b"><th class="p-3">Tenant</th><th class="p-3">Invoice</th><th class="p-3">Amount</th><th class="p-3">Status</th><th class="p-3">Action</th></tr></thead><tbody><?php foreach($payments as $payment): ?><tr class="border-b"><td class="p-3"><?=e($payment['full_name'])?></td><td class="p-3"><?=e($payment['month_year'])?></td><td class="p-3"><?=money($payment['amount'])?></td><td class="p-3"><?=badge($payment['status'])?></td><td class="p-3"><?php if($payment['status']==='pending'): ?><form class="flex gap-2" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="payment_id" value="<?=e((string)$payment['id'])?>"><button class="rounded bg-emerald-700 px-3 py-1 text-white" name="action" value="approved">Approve</button><button class="rounded bg-rose-700 px-3 py-1 text-white" name="action" value="rejected">Reject</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php pageFooter(); ?>